-- 세트 48: grep 천천히 익히기: 글자로 줄 찾기
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (48, 1, 'grep 과 find 의 차이, grep 의 기본 구조 알기', '`grep "ERROR" /var/log/app.log` 는 어떤 뜻일까요?', '`grep` 은 파일 **안의 글자(줄)** 를 찾습니다. 형태는 `grep 옵션 찾을글자 파일` 입니다.', NULL, NULL, '[]', 'choice', '["`/var/log/app.log` 파일 **안에서** `ERROR` 라는 글자가 든 **줄**을 찾아 출력한다", "`ERROR` 라는 **이름**의 파일을 `/var/log` 에서 찾는다", "`app.log` 안의 `ERROR` 를 지운다", "`app.log` 를 `ERROR` 로 복사한다"]', 0, '`grep 찾을글자 파일` 은 파일 **안의 내용**에서 글자가 들어 있는 **줄**을 골라 보여 줍니다. 파일·폴더의 **이름이나 속성**을 찾는 것은 `find` 입니다. 옵션은 `-i`, `-n` 처럼 `-` 로 시작하며 찾을 글자 앞에 놓습니다.', NULL, NULL, NULL, NULL),
  (48, 2, 'grep 명령 한 줄을 올바른 순서로 조립하기', '`/var/log/app.log` 에서 `ERROR` 가 든 줄을 **줄 번호와 함께** 찾는 명령의 조각이 섞여 있습니다. **왼쪽에서 오른쪽 순서**대로 놓으세요.', '명령 이름, 옵션, 찾을 글자, 파일 순서입니다.', NULL, NULL, '[]', 'order', '["`\\"ERROR\\"` (찾을 글자)", "`/var/log/app.log` (파일)", "`grep` (명령)", "`-n` (옵션: 줄 번호)"]', NULL, '`grep -n "ERROR" /var/log/app.log` 순서입니다. 명령, 옵션, 찾을 글자, 대상 파일 순서이고 `-` 로 시작하는 옵션은 찾을 글자 앞에 둡니다.', '[2, 3, 0, 1]', NULL, NULL, NULL),
  (48, 3, '글자가 든 줄만 찾아 저장하기 (grep 기본)', '`/tmp/app.log` 는 서버 로그입니다. 이 파일에서 **`ERROR` 라는 글자가 든 줄**만 찾아 `/tmp/errors.txt` 에 저장하세요.', '`grep 찾을글자 파일` 형태입니다. 결과는 화면에 나오므로 `>` 로 파일에 저장합니다.
확인: `cat /tmp/errors.txt`', 'grep ERROR /tmp/app.log > /tmp/errors.txt

# grep ERROR 파일 : 파일에서 ERROR 가 든 줄만 출력
# > 파일          : 결과를 저장
# 대소문자를 구분하므로 소문자 error 줄은 나오지 않는다', '["sh", "-c", "printf ''2026-01-01 INFO server started\\\\n2026-01-01 ERROR db connection failed\\\\n2026-01-02 error disk almost full\\\\n2026-01-02 WARN slow query\\\\n2026-01-03 INFO request ok\\\\n2026-01-03 ERROR timeout on api\\\\n'' > /tmp/app.log"]', '["sh", "-c", "( [ -s /tmp/errors.txt ] ) && ( [ \\"$(wc -l < /tmp/errors.txt)\\" -eq 2 ] ) && ( grep -q \\"db connection failed\\" /tmp/errors.txt ) && ( grep -q \\"timeout on api\\" /tmp/errors.txt ) && ( ! grep -qE \\"INFO|WARN|error disk\\" /tmp/errors.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/errors.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/errors.txt ]"]}, {"label": "대문자 ERROR 줄 2개만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/errors.txt)\\" -eq 2 ]"]}, {"label": "db 연결 실패 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"db connection failed\\" /tmp/errors.txt"]}, {"label": "api 타임아웃 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"timeout on api\\" /tmp/errors.txt"]}, {"label": "다른 줄은 들어 있지 않다", "cmd": ["sh", "-c", "! grep -qE \\"INFO|WARN|error disk\\" /tmp/errors.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 4, '대소문자 구분 없이 찾기 (-i)', '앞 문제에서는 소문자 `error disk almost full` 줄이 빠졌습니다. 이번에는 **대문자든 소문자든 `error` 가 든 줄 모두**를 `/tmp/all_errors.txt` 에 저장하세요.', '찾는 방법: `grep --help | grep -i case` 로 대소문자와 관련된 옵션을 찾아보세요. (ignore-case)
확인: `cat /tmp/all_errors.txt`', 'grep -i error /tmp/app.log > /tmp/all_errors.txt

# -i : 대소문자를 구분하지 않는다 (ignore case)', '["sh", "-c", "printf ''2026-01-01 INFO server started\\\\n2026-01-01 ERROR db connection failed\\\\n2026-01-02 error disk almost full\\\\n2026-01-02 WARN slow query\\\\n2026-01-03 INFO request ok\\\\n2026-01-03 ERROR timeout on api\\\\n'' > /tmp/app.log"]', '["sh", "-c", "( [ -s /tmp/all_errors.txt ] ) && ( [ \\"$(wc -l < /tmp/all_errors.txt)\\" -eq 3 ] ) && ( grep -q \\"disk almost full\\" /tmp/all_errors.txt ) && ( ! grep -qE \\"INFO|WARN\\" /tmp/all_errors.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/all_errors.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/all_errors.txt ]"]}, {"label": "3줄이다 (ERROR 2줄 + error 1줄)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/all_errors.txt)\\" -eq 3 ]"]}, {"label": "소문자 error 줄이 들어 있다", "cmd": ["sh", "-c", "grep -q \\"disk almost full\\" /tmp/all_errors.txt"]}, {"label": "ERROR/error 가 아닌 줄은 없다", "cmd": ["sh", "-c", "! grep -qE \\"INFO|WARN\\" /tmp/all_errors.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 5, '주석 줄을 빼고 보기 (-v)', '`/tmp/app.conf` 설정 파일에는 `#` 로 시작하는 주석 줄이 섞여 있습니다. **주석이 아닌 줄만** `/tmp/clean.conf` 에 저장하세요.', '`-v` 는 "찾은 줄을 **뺀** 나머지"를 보여 줍니다. 줄의 **맨 앞**을 뜻하는 기호는 `^` 입니다. 즉 `^#` 는 "# 로 시작하는 줄"입니다. 쉘이 해석하지 않도록 `''^#''` 처럼 따옴표로 감싸세요.
확인: `cat /tmp/clean.conf`', 'grep -v ''^#'' /tmp/app.conf > /tmp/clean.conf

# -v    : 패턴과 맞는 줄을 제외한 나머지 (invert)
# ''^#''  : 줄 맨 앞(^)이 # 인 줄 = 주석', '["sh", "-c", "printf ''# main config\\\\nport=8080\\\\n# debug off\\\\ndebug=false\\\\nhost=0.0.0.0\\\\n'' > /tmp/app.conf"]', '["sh", "-c", "( [ -s /tmp/clean.conf ] ) && ( [ \\"$(wc -l < /tmp/clean.conf)\\" -eq 3 ] ) && ( ! grep -qE \\"#\\" /tmp/clean.conf ) && ( grep -q \\"port=8080\\" /tmp/clean.conf )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/clean.conf 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/clean.conf ]"]}, {"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/clean.conf)\\" -eq 3 ]"]}, {"label": "# 로 시작하는 주석 줄이 없다", "cmd": ["sh", "-c", "! grep -qE \\"#\\" /tmp/clean.conf"]}, {"label": "설정 줄(port=8080)이 들어 있다", "cmd": ["sh", "-c", "grep -q \\"port=8080\\" /tmp/clean.conf"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 6, '줄 번호와 함께 찾기 (-n)', '`/tmp/app.log` 에서 `ERROR` 가 든 줄을 **몇 번째 줄인지 번호와 함께** `/tmp/error_lines.txt` 에 저장하세요. (`2:...` 처럼 번호가 앞에 붙습니다)', '찾는 방법: `grep --help | grep -i "line number"`
확인: `cat /tmp/error_lines.txt`', 'grep -n ERROR /tmp/app.log > /tmp/error_lines.txt

# -n : 줄 번호를 앞에 붙인다 (number)', '["sh", "-c", "printf ''2026-01-01 INFO server started\\\\n2026-01-01 ERROR db connection failed\\\\n2026-01-02 error disk almost full\\\\n2026-01-02 WARN slow query\\\\n2026-01-03 INFO request ok\\\\n2026-01-03 ERROR timeout on api\\\\n'' > /tmp/app.log"]', '["sh", "-c", "( [ -s /tmp/error_lines.txt ] ) && ( [ \\"$(wc -l < /tmp/error_lines.txt)\\" -eq 2 ] ) && ( grep -q \\"^2:\\" /tmp/error_lines.txt ) && ( grep -q \\"^6:\\" /tmp/error_lines.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/error_lines.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/error_lines.txt ]"]}, {"label": "ERROR 줄 2개다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/error_lines.txt)\\" -eq 2 ]"]}, {"label": "2번째 줄이 `2:` 로 시작한다", "cmd": ["sh", "-c", "grep -q \\"^2:\\" /tmp/error_lines.txt"]}, {"label": "6번째 줄이 `6:` 로 시작한다", "cmd": ["sh", "-c", "grep -q \\"^6:\\" /tmp/error_lines.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 7, '몇 줄인지 세기 (-c)', '`/tmp/app.log` 에 `INFO` 가 든 줄이 **몇 개**인지 숫자만 `/tmp/info_count.txt` 에 저장하세요.', '찾는 방법: `grep --help | grep -i count`
확인: `cat /tmp/info_count.txt`', 'grep -c INFO /tmp/app.log > /tmp/info_count.txt

# -c : 줄을 출력하지 않고 맞는 줄의 개수만 출력 (count)', '["sh", "-c", "printf ''2026-01-01 INFO server started\\\\n2026-01-01 ERROR db connection failed\\\\n2026-01-02 error disk almost full\\\\n2026-01-02 WARN slow query\\\\n2026-01-03 INFO request ok\\\\n2026-01-03 ERROR timeout on api\\\\n'' > /tmp/app.log"]', '["sh", "-c", "( [ -s /tmp/info_count.txt ] ) && ( [ \\"$(cat /tmp/info_count.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/info_count.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/info_count.txt ]"]}, {"label": "숫자 2 한 줄만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/info_count.txt)\\" = 2 ]"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 8, '단어 단위로만 찾기 (-w)', '`/tmp/words.txt` 에서 **`cat` 이라는 단어**가 든 줄만 `/tmp/cat_only.txt` 에 저장하세요. `category`, `concatenate`, `bobcat` 처럼 `cat` 이 **다른 단어의 일부**인 줄은 빼야 합니다.', '찾는 방법: `grep --help | grep -i word`
그냥 `grep cat` 을 실행해 보면 5줄이 모두 나옵니다. 차이를 비교해 보세요.
확인: `cat /tmp/cat_only.txt`', 'grep -w cat /tmp/words.txt > /tmp/cat_only.txt

# -w : 글자가 한 단어로 따로 있는 줄만 (word)', '["sh", "-c", "printf ''cat\\\\nconcatenate\\\\nthe cat sat\\\\ncategory\\\\nbobcat\\\\n'' > /tmp/words.txt"]', '["sh", "-c", "( [ -s /tmp/cat_only.txt ] ) && ( [ \\"$(wc -l < /tmp/cat_only.txt)\\" -eq 2 ] ) && ( grep -q \\"the cat sat\\" /tmp/cat_only.txt ) && ( ! grep -qE \\"category|concatenate|bobcat\\" /tmp/cat_only.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/cat_only.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/cat_only.txt ]"]}, {"label": "2줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/cat_only.txt)\\" -eq 2 ]"]}, {"label": "`the cat sat` 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"the cat sat\\" /tmp/cat_only.txt"]}, {"label": "단어의 일부로만 든 줄은 없다", "cmd": ["sh", "-c", "! grep -qE \\"category|concatenate|bobcat\\" /tmp/cat_only.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 9, '폴더 아래 모든 파일에서 찾기 (-r)', '`/tmp/proj` 폴더 아래(하위 폴더 포함)의 파일 중 **`password` 가 든 줄**을 찾아 `/tmp/pw.txt` 에 저장하세요. 어느 파일에서 나왔는지도 함께 나옵니다.', '찾는 방법: `grep --help | grep -i recursive`
파일 이름 자리에 **폴더**를 적습니다.
확인: `cat /tmp/pw.txt`', 'grep -r password /tmp/proj > /tmp/pw.txt

# -r : 폴더 아래를 하위 폴더까지 모두 뒤진다 (recursive)
# 여러 파일을 뒤지면 결과 앞에 파일 이름이 붙는다', '["sh", "-c", "mkdir -p /tmp/proj/app/sub && printf ''user=admin\\\\npassword=abc\\\\n'' > /tmp/proj/app/settings.ini && printf ''db_password=xyz\\\\nhost=db1\\\\n'' > /tmp/proj/app/sub/db.ini && printf ''no secrets here\\\\n'' > /tmp/proj/readme.txt"]', '["sh", "-c", "( [ -s /tmp/pw.txt ] ) && ( [ \\"$(wc -l < /tmp/pw.txt)\\" -eq 2 ] ) && ( grep -q \\"settings.ini\\" /tmp/pw.txt ) && ( grep -q \\"sub/db.ini\\" /tmp/pw.txt ) && ( ! grep -qE \\"readme\\" /tmp/pw.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/pw.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/pw.txt ]"]}, {"label": "2줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/pw.txt)\\" -eq 2 ]"]}, {"label": "settings.ini 에서 찾은 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"settings.ini\\" /tmp/pw.txt"]}, {"label": "하위 폴더 sub/db.ini 에서 찾은 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"sub/db.ini\\" /tmp/pw.txt"]}, {"label": "관련 없는 readme.txt 는 없다", "cmd": ["sh", "-c", "! grep -qE \\"readme\\" /tmp/pw.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 10, '글자가 든 파일의 이름만 보기 (-l)', '같은 `/tmp/proj` 에서 이번에는 줄 내용은 필요 없고, **`password` 가 든 파일의 경로만** `/tmp/pw_files.txt` 에 저장하세요. (파일마다 한 줄)', '찾는 방법: `grep --help | grep -i "file names"` 또는 `grep --help | grep -i matching`
`-r` 과 함께 쓸 수 있습니다. 옵션 두 개는 `-rl` 처럼 붙여 쓸 수 있습니다.
확인: `cat /tmp/pw_files.txt`', 'grep -rl password /tmp/proj > /tmp/pw_files.txt

# -r : 하위 폴더까지
# -l : 맞는 줄 대신 파일 이름만 출력 (files with matches)', '["sh", "-c", "mkdir -p /tmp/proj/app/sub && printf ''user=admin\\\\npassword=abc\\\\n'' > /tmp/proj/app/settings.ini && printf ''db_password=xyz\\\\nhost=db1\\\\n'' > /tmp/proj/app/sub/db.ini && printf ''no secrets here\\\\n'' > /tmp/proj/readme.txt"]', '["sh", "-c", "( [ -s /tmp/pw_files.txt ] ) && ( [ \\"$(wc -l < /tmp/pw_files.txt)\\" -eq 2 ] ) && ( grep -q \\"settings.ini\\" /tmp/pw_files.txt ) && ( grep -q \\"db.ini\\" /tmp/pw_files.txt ) && ( ! grep -qE \\"=\\" /tmp/pw_files.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/pw_files.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/pw_files.txt ]"]}, {"label": "파일 2개 경로다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/pw_files.txt)\\" -eq 2 ]"]}, {"label": "settings.ini 경로가 있다", "cmd": ["sh", "-c", "grep -q \\"settings.ini\\" /tmp/pw_files.txt"]}, {"label": "db.ini 경로가 있다", "cmd": ["sh", "-c", "grep -q \\"db.ini\\" /tmp/pw_files.txt"]}, {"label": "줄 내용(`=` 이 든 글자)은 없고 경로만 있다", "cmd": ["sh", "-c", "! grep -qE \\"=\\" /tmp/pw_files.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 11, '둘 중 하나라도 있는 줄 찾기 (-E 와 |)', '`/tmp/app.log` 에서 **`ERROR` 또는 `WARN`** 이 든 줄을 모두 `/tmp/problems.txt` 에 저장하세요.', '찾는 방법: `grep --help | grep -i regexp`
`-E` 를 쓰면 `A|B` 로 "A 또는 B"를 적을 수 있습니다. `|` 가 쉘의 파이프로 해석되지 않도록 패턴을 따옴표로 감싸세요.
확인: `cat /tmp/problems.txt`', 'grep -E "ERROR|WARN" /tmp/app.log > /tmp/problems.txt

# -E      : 확장 정규식 (| 로 "또는"을 쓸 수 있다)
# "A|B"   : A 또는 B (따옴표로 쉘 파이프와 구분)', '["sh", "-c", "printf ''2026-01-01 INFO server started\\\\n2026-01-01 ERROR db connection failed\\\\n2026-01-02 error disk almost full\\\\n2026-01-02 WARN slow query\\\\n2026-01-03 INFO request ok\\\\n2026-01-03 ERROR timeout on api\\\\n'' > /tmp/app.log"]', '["sh", "-c", "( [ -s /tmp/problems.txt ] ) && ( [ \\"$(wc -l < /tmp/problems.txt)\\" -eq 3 ] ) && ( grep -q \\"slow query\\" /tmp/problems.txt ) && ( grep -q \\"db connection failed\\" /tmp/problems.txt ) && ( ! grep -qE \\"INFO\\" /tmp/problems.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/problems.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/problems.txt ]"]}, {"label": "3줄이다 (ERROR 2줄 + WARN 1줄)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/problems.txt)\\" -eq 3 ]"]}, {"label": "WARN 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"slow query\\" /tmp/problems.txt"]}, {"label": "ERROR 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"db connection failed\\" /tmp/problems.txt"]}, {"label": "INFO 줄은 없다", "cmd": ["sh", "-c", "! grep -qE \\"INFO\\" /tmp/problems.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 12, '맞는 부분만 뽑아내기 (-o)', '`/tmp/users.log` 에서 줄 전체가 아니라 **`user=이름` 부분만** 뽑아 `/tmp/users.txt` 에 저장하세요. (이름은 소문자 알파벳)

`login user=kim ok` → `user=kim`', '찾는 방법: `grep --help | grep -i only`
패턴 `user=[a-z]*` 에서 `[a-z]` 는 소문자 한 글자, `*` 는 앞의 것이 0번 이상 반복입니다.
확인: `cat /tmp/users.txt`', 'grep -o ''user=[a-z]*'' /tmp/users.log > /tmp/users.txt

# -o          : 줄 전체가 아니라 맞는 부분만 출력 (only matching)
# user=[a-z]* : user= 뒤에 소문자가 이어지는 부분', '["sh", "-c", "printf ''login user=kim ok\\\\nlogin user=lee ok\\\\nlogout user=kim\\\\n'' > /tmp/users.log"]', '["sh", "-c", "( [ -s /tmp/users.txt ] ) && ( [ \\"$(wc -l < /tmp/users.txt)\\" -eq 3 ] ) && ( ! grep -qvE \\"^user=[a-z]+$\\" /tmp/users.txt ) && ( grep -q \\"user=lee\\" /tmp/users.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/users.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/users.txt ]"]}, {"label": "3줄이다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/users.txt)\\" -eq 3 ]"]}, {"label": "모든 줄이 `user=이름` 모양이다 (login/ok 같은 글자는 없다)", "cmd": ["sh", "-c", "! grep -qvE \\"^user=[a-z]+$\\" /tmp/users.txt"]}, {"label": "lee 도 들어 있다", "cmd": ["sh", "-c", "grep -q \\"user=lee\\" /tmp/users.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 13, '찾은 줄의 앞뒤 줄도 함께 보기 (-A, -B)', '`/tmp/trace.log` 에서 `ERROR` 가 든 줄과 **그 바로 다음 1줄**(원인이 적혀 있습니다)을 `/tmp/ctx.txt` 에 저장하세요.', '찾는 방법: `grep --help | grep -i context`
"뒤(After)로 몇 줄", "앞(Before)으로 몇 줄"을 정하는 옵션이 따로 있습니다.
확인: `cat /tmp/ctx.txt`', 'grep -A 1 ERROR /tmp/trace.log > /tmp/ctx.txt

# -A 1 : 찾은 줄과 그 뒤 1줄 (After)
# -B 1 : 찾은 줄과 그 앞 1줄 (Before)
# -C 1 : 앞뒤로 1줄씩 (Context)', '["sh", "-c", "printf ''start job\\\\nERROR job failed\\\\nreason: out of memory\\\\nretry scheduled\\\\nend\\\\n'' > /tmp/trace.log"]', '["sh", "-c", "( [ -s /tmp/ctx.txt ] ) && ( [ \\"$(wc -l < /tmp/ctx.txt)\\" -eq 2 ] ) && ( grep -q \\"job failed\\" /tmp/ctx.txt ) && ( grep -q \\"out of memory\\" /tmp/ctx.txt ) && ( ! grep -qE \\"start job|retry\\" /tmp/ctx.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/ctx.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/ctx.txt ]"]}, {"label": "2줄이다 (ERROR 줄 + 다음 줄)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/ctx.txt)\\" -eq 2 ]"]}, {"label": "ERROR 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"job failed\\" /tmp/ctx.txt"]}, {"label": "다음 줄(원인)이 있다", "cmd": ["sh", "-c", "grep -q \\"out of memory\\" /tmp/ctx.txt"]}, {"label": "앞뒤의 다른 줄은 없다", "cmd": ["sh", "-c", "! grep -qE \\"start job|retry\\" /tmp/ctx.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]'),
  (48, 14, '옵션 합쳐 쓰기: 모든 로그에서 timeout 줄을 파일·줄 번호와 함께', '`/tmp/srv/logs` 아래(하위 폴더 포함)의 모든 파일에서 **대소문자 상관없이 `timeout` 이 든 줄**을 찾아, **어느 파일 몇 번째 줄인지**가 함께 보이게 `/tmp/timeouts.txt` 에 저장하세요.', '지금까지 배운 옵션을 합칩니다: 하위 폴더까지(`-r`), 대소문자 무시(`-i`), 줄 번호(`-n`). 옵션은 `-rin` 처럼 붙여 쓸 수 있습니다.
확인: `cat /tmp/timeouts.txt` (결과 앞에 `경로:줄번호:` 가 붙어야 합니다)', 'grep -rin timeout /tmp/srv/logs > /tmp/timeouts.txt

# -r : 하위 폴더까지
# -i : 대소문자 무시 (Timeout, TIMEOUT 도 찾는다)
# -n : 줄 번호
# 여러 파일을 뒤지므로 파일 경로도 자동으로 붙는다', '["sh", "-c", "mkdir -p /tmp/srv/logs/db && printf ''GET / 200\\\\nTimeout waiting for upstream\\\\nGET /x 200\\\\n'' > /tmp/srv/logs/web.log && printf ''connected\\\\nquery TIMEOUT after 30s\\\\nok\\\\n'' > /tmp/srv/logs/db/db.log && printf ''all good\\\\n'' > /tmp/srv/logs/notes.txt"]', '["sh", "-c", "( [ -s /tmp/timeouts.txt ] ) && ( [ \\"$(wc -l < /tmp/timeouts.txt)\\" -eq 2 ] ) && ( grep -q \\"web.log:2:\\" /tmp/timeouts.txt ) && ( grep -q \\"db/db.log:2:\\" /tmp/timeouts.txt ) && ( grep -q \\"TIMEOUT\\" /tmp/timeouts.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "결과 파일 /tmp/timeouts.txt 가 있다", "cmd": ["sh", "-c", "[ -s /tmp/timeouts.txt ]"]}, {"label": "2줄이다 (두 파일에서 한 줄씩)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/timeouts.txt)\\" -eq 2 ]"]}, {"label": "web.log 의 2번째 줄이 `경로:2:` 형태로 있다", "cmd": ["sh", "-c", "grep -q \\"web.log:2:\\" /tmp/timeouts.txt"]}, {"label": "하위 폴더 db/db.log 의 2번째 줄이 있다", "cmd": ["sh", "-c", "grep -q \\"db/db.log:2:\\" /tmp/timeouts.txt"]}, {"label": "대문자 TIMEOUT 줄도 들어 있다", "cmd": ["sh", "-c", "grep -q \\"TIMEOUT\\" /tmp/timeouts.txt"]}]', '[{"title": "GNU grep 매뉴얼", "url": "https://www.gnu.org/software/grep/manual/grep.html"}]');
